<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();$message=null;if(isset($_GET['id'])){$q=$db->prepare('SELECT m.*,u.username sender FROM private_messages m JOIN users u ON u.id=m.sender_id WHERE m.id=? AND m.recipient_id=?');$q->execute([(int)$_GET['id'],$currentUser['id']]);$message=$q->fetch();if($message)$db->prepare('UPDATE private_messages SET is_read=1 WHERE id=?')->execute([$message['id']]);}if(page_post()){check_csrf();$to=trim((string)($_POST['to']??''));$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));$q=$db->prepare('SELECT id FROM users WHERE username=?');$q->execute([$to]);$recipient=$q->fetch();if(!$recipient||$subject===''||$body===''){notice('Check the recipient, subject and message.','error');go('/My/PrivateMessage.php');}$db->prepare('INSERT INTO private_messages(sender_id,recipient_id,subject,body) VALUES(?,?,?,?)')->execute([$currentUser['id'],$recipient['id'],$subject,$body]);notice('Message sent.');go('/My/Inbox.php');}page_start('Private Message');?><section class="Panel"><?php if($message):?><h1><?=e($message['subject'])?></h1><p>From <?=e($message['sender'])?> · <?=e($message['created_at'])?></p><p><?=nl2br(e($message['body']))?></p><a href="/My/Inbox.php">Back to inbox</a><?php else:?><h1>Compose Message</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>To (username)<input name="to" value="<?=e((string)($_GET['to']??''))?>" required></label><label>Subject<input name="subject" maxlength="120" required></label><label>Message<textarea name="body" required></textarea></label><button class="Button">Send</button></form><?php endif;?></section><?php page_end();